-- NEXUS 2D DESIGN ASSET SYSTEM
--========================================================

local NEXUS_ASSETS = {
    'combat' = '',
    'config' = '',
    'crown' = '',
    'home' = '',
    'load' = '',
    'movement' = '',
    'player' = '',
    'save' = '',
    'settings' = '',
    'teleport' = '',
    'visual' = '',
}

local NexusAssetCache = {}
local NexusAssetGetter = nil

if type(getcustomasset) == "function" then
    NexusAssetGetter = getcustomasset
elseif type(getsynasset) == "function" then
    NexusAssetGetter = getsynasset
elseif type(syn) == "table" and type(syn.getcustomasset) == "function" then
    NexusAssetGetter = syn.getcustomasset
end

local BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function decodeBase64(data)
    local clean = data:gsub("[^" .. BASE64_ALPHABET .. "=]", "")
    local out, buffer, bits = {}, 0, 0

    for i = 1, #clean do
        local ch = clean:sub(i, i)
        if ch ~= "=" then
            local n = BASE64_ALPHABET:find(ch, 1, true)
            if n then
                buffer = buffer * 64 + (n - 1)
                bits += 6
                if bits >= 8 then
                    bits -= 8
                    out[#out + 1] = string.char(math.floor(buffer / (2 ^ bits)) % 256)
                end
            end
        end
    end

    return table.concat(out)
end

local function nexusAsset(kind)
    if NexusAssetCache[kind] then
        return NexusAssetCache[kind]
    end

    if not (NexusAssetGetter and HAS.writefile and NEXUS_ASSETS[kind]) then
        return nil
    end

    local folder = "Nexus_Assets"
    if HAS.makefolder and HAS.isfolder then
        pcall(function()
            if not isfolder(folder) then
                makefolder(folder)
            end
        end)
    end

    local file = folder .. "/" .. kind .. ".png"

    local ok = pcall(function()
        if not (HAS.isfile and isfile(file)) then
            writefile(file, decodeBase64(NEXUS_ASSETS[kind]))
        end
    end)

    if not ok then
        return nil
    end

    local good, asset = pcall(function()
        return NexusAssetGetter(file)
    end)

    if good and asset then
        NexusAssetCache[kind] = asset
        return asset
    end

    return nil
end
