--========================================================
-- FACTORIES
--========================================================

local function New(className, props)
    local object = Instance.new(className)
    for property, value in pairs(props or {}) do
        object[property] = value
    end
    return track(object)
end

local function Corner(parent, radius)
    return New("UICorner", {
        Parent = parent,
        CornerRadius = UDim.new(0, radius),
    })
end

local function Border(parent, color, thickness, transparency)
    return New("UIStroke", {
        Parent = parent,
        Color = color,
        Thickness = thickness or 1,
        Transparency = transparency or 0,
    })
end

local function Gradient(parent, a, b, rotation)
    return New("UIGradient", {
        Parent = parent,
        Color = ColorSequence.new(a, b),
        Rotation = rotation or 0,
    })
end

local function tween(object, properties, duration, style, direction)
    local info = TweenInfo.new(
        duration or 0.2,
        style or Enum.EasingStyle.Quint,
        direction or Enum.EasingDirection.Out
    )

    local animation = TweenService:Create(object, info, properties)
    animation:Play()
    return animation
end

local function text(parent, value, size, pos, font, color)
    return New("TextLabel", {
        Parent = parent,
        BackgroundTransparency = 1,
        Text = value or "",
        Font = font or FONT,
        TextSize = size or 12,
        TextColor3 = color or C.Text,
        Position = pos or UDim2.new(),
        Size = UDim2.new(1, 0, 0, 24),
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Center,
        ZIndex = parent.ZIndex + 1,
    })
end

local function makeButton(parent, size, pos)
    local button = New("TextButton", {
        Parent = parent,
        BackgroundColor3 = C.Surface2,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Text = "",
        Size = size,
        Position = pos,
        ZIndex = parent.ZIndex + 2,
    })
    Corner(button, 10)
    Border(button, C.Stroke, 1, 0.15)

    trackConnection(button.MouseEnter:Connect(function()
        tween(button, {BackgroundColor3 = C.Surface3}, 0.12)
    end))

    trackConnection(button.MouseLeave:Connect(function()
        tween(button, {BackgroundColor3 = C.Surface2}, 0.16)
    end))

    return button
end

