local ICON_ASSET_MAP = {
    crown = "crown", home = "home", crosshair = "combat", eye = "visual",
    movement = "movement", player = "player", teleport = "teleport",
    config = "config", settings = "settings", load = "load", save = "save",
}

local function makeImageLogo(parent, kind, size, position, tint, transparency, z)
    return New("ImageLabel", {
        Parent = parent,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Size = size or UDim2.fromOffset(28, 28),
        Position = position or UDim2.new(),
        Image = nexusAsset(kind) or "",
        ImageColor3 = tint or C.White,
        ImageTransparency = transparency or 0,
        ScaleType = Enum.ScaleType.Fit,
        ZIndex = z or (parent.ZIndex + 2),
    })
end

local function makeCrown(parent, accent, scale, position)
    scale = scale or 1
    local holderSize = 40 * scale
    local holder = New("Frame", {
        Parent = parent,
        BackgroundTransparency = 1,
        Position = position or UDim2.new(),
        Size = UDim2.fromOffset(holderSize, holderSize),
        ZIndex = parent.ZIndex + 3,
    })

    local glow = makeImageLogo(
        holder, "crown",
        UDim2.fromOffset(holderSize * 1.10, holderSize * 1.10),
        UDim2.fromOffset(-holderSize * 0.05, -holderSize * 0.05),
        accent or C.PurpleBright, 0.76, holder.ZIndex
    )
    glow.Name = "NexusCrownGlow"

    local logo = makeImageLogo(
        holder, "crown",
        UDim2.fromOffset(holderSize, holderSize),
        UDim2.new(),
        C.White, 0, holder.ZIndex + 1
    )
    logo.Name = "NexusCrownLogo"

    return holder
end

local function makeVectorIcon(parent, kind, accent, size)
    local assetKind = ICON_ASSET_MAP[kind] or "config"
    local icon = makeImageLogo(
        parent, assetKind, UDim2.fromOffset(size or 26, size or 26),
        UDim2.new(), accent or C.White, 0, parent.ZIndex + 2
    )
    icon.Name = "NexusIcon"
    return icon
end

