--========================================================
-- RESPONSIVE WINDOW
--========================================================

local function viewportSize()
    local camera = workspace.CurrentCamera
    return camera and camera.ViewportSize or Vector2.new(1280, 720)
end

local function calculateWindow()
    local size = viewportSize()

    if size.X <= 540 then
        return UDim2.new(1, -18, 0, math.clamp(size.Y - 105, 350, 560))
    elseif size.X <= 900 then
        local width = math.clamp(size.X - 54, 580, 860)
        local height = math.clamp(size.Y - 108, 390, 540)
        return UDim2.fromOffset(width, height)
    else
        local width = math.min(1190, math.floor(size.X * 0.79))
        local height = math.min(520, math.floor(size.Y * 0.70))
        return UDim2.fromOffset(width, math.max(440, height))
    end
end

