local function page(name)
    local p = New("ScrollingFrame", {
        Parent = Content,
        Name = name,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Size = UDim2.fromScale(1, 1),
        Visible = false,
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        CanvasSize = UDim2.new(),
        ScrollBarThickness = 3,
        ScrollBarImageColor3 = C.Purple,
        ZIndex = 42,
    })

    New("UIPadding", {
        Parent = p,
        PaddingBottom = UDim.new(0, 12),
        PaddingRight = UDim.new(0, 4),
    })

    New("UIListLayout", {
        Parent = p,
        Padding = UDim.new(0, 9),
        SortOrder = Enum.SortOrder.LayoutOrder,
    })

    Pages[name] = p
    return p
end

local function pageTitle(p, title, subtitle, accent)
    local box = New("Frame", {
        Parent = p,
        BackgroundColor3 = C.Surface,
        BorderSizePixel = 0,
        Size = UDim2.new(1, -4, 0, 64),
        ZIndex = 43,
    })
    Corner(box, 14)
    Border(box, accent or C.Purple, 1.1, 0.22)

    local accentBar = New("Frame", {
        Parent = box,
        BackgroundColor3 = accent or C.Purple,
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(3, 32),
        Position = UDim2.fromOffset(10, 16),
        ZIndex = 44,
    })
    Corner(accentBar, 99)

    local t = text(box, title, 18, UDim2.fromOffset(22, 7), BOLD, C.White)
    t.Size = UDim2.new(1, -32, 0, 25)

    local s = text(box, subtitle or "", 9, UDim2.fromOffset(22, 34), FONT, C.SubText)
    s.Size = UDim2.new(1, -32, 0, 20)

    return box
end

local function section(p, title, height, accent)
    local box = New("Frame", {
        Parent = p,
        BackgroundColor3 = C.Card,
        BorderSizePixel = 0,
        Size = UDim2.new(1, -4, 0, height),
        ZIndex = 43,
    })
    Corner(box, 14)
    Border(box, accent or C.Stroke, 1, 0.22)

    local titleLabel = text(box, title, 11, UDim2.fromOffset(13, 8), BOLD, C.Text)
    titleLabel.Size = UDim2.new(1, -26, 0, 22)

    return box
end

local function toggle(parent, labelText, y, accent)
    local row = New("Frame", {
        Parent = parent,
        BackgroundColor3 = C.Surface,
        BorderSizePixel = 0,
        Position = UDim2.new(0, 10, 0, y),
        Size = UDim2.new(1, -20, 0, 34),
        ZIndex = 44,
    })
    Corner(row, 9)

    local tiny = New("Frame", {
        Parent = row,
        BackgroundColor3 = accent,
        BorderSizePixel = 0,
        Position = UDim2.fromOffset(0, 0),
        Size = UDim2.fromOffset(2, 34),
        ZIndex = 45,
    })
    Corner(tiny, 99)

    local l = text(row, labelText, 10, UDim2.fromOffset(10, 0), FONT, C.Text)
    l.Size = UDim2.new(1, -64, 1, 0)

    local switch = New("TextButton", {
        Parent = row,
        BackgroundColor3 = C.Surface2,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Text = "",
        Position = UDim2.new(1, -46, 0.5, -8),
        Size = UDim2.fromOffset(36, 16),
        ZIndex = 46,
    })
    Corner(switch, 99)
    Border(switch, C.Stroke, 1, 0.2)

    local knob = New("Frame", {
        Parent = switch,
        BackgroundColor3 = C.Muted,
        BorderSizePixel = 0,
        Position = UDim2.fromOffset(3, 3),
        Size = UDim2.fromOffset(10, 10),
        ZIndex = 47,
    })
    Corner(knob, 99)

    local state = false

    local function setState(value)
        state = value

        tween(switch, {
            BackgroundColor3 = value and Color3.fromRGB(46, 24, 79) or C.Surface2,
        }, 0.14)

        tween(knob, {
            Position = value and UDim2.new(1, -13, 0, 3) or UDim2.fromOffset(3, 3),
            BackgroundColor3 = value and accent or C.Muted,
        }, 0.14)
    end

    trackConnection(switch.MouseButton1Click:Connect(function()
        setState(not state)
    end))

    return row, setState, function()
        return state
    end
end

local function action(parent, labelText, y, accent)
    local button = makeButton(
        parent,
        UDim2.new(1, -20, 0, 34),
        UDim2.new(0, 10, 0, y)
    )

    Border(button, accent or C.Stroke, 1.1, 0.25)

    local marker = New("Frame", {
        Parent = button,
        BackgroundColor3 = Color3.fromRGB(31, 18, 57),
        BackgroundTransparency = 0.08,
        BorderSizePixel = 0,
        Position = UDim2.fromOffset(6, 4),
        Size = UDim2.fromOffset(28, 28),
        ZIndex = 47,
    })
    Corner(marker, 9)
    Border(marker, accent or C.Purple, 1, 0.15)

    local lowerLabel = string.lower(labelText)
    local iconKind = "config"
    if string.find(lowerLabel, "teleport") then
        iconKind = "teleport"
    elseif string.find(lowerLabel, "load") then
        iconKind = "load"
    elseif string.find(lowerLabel, "save") then
        iconKind = "save"
    end

    local actionIcon = makeVectorIcon(marker, iconKind, accent or C.White, 20)
    actionIcon.Position = UDim2.fromOffset(4, 4)
    actionIcon.Name = "NexusActionIcon"
    actionIcon.Position = UDim2.fromOffset(3, 3)

    local l = text(button, labelText, 10, UDim2.fromOffset(40, 0), BOLD, C.Text)
    l.Size = UDim2.new(1, -70, 1, 0)

    local arrow = text(button, "›", 15, UDim2.new(1, -28, 0, 0), BOLD, accent or C.SubText)
    arrow.Size = UDim2.fromOffset(17, 34)
    arrow.TextXAlignment = Enum.TextXAlignment.Center

    trackConnection(button.MouseEnter:Connect(function()
        tween(button, {
            BackgroundColor3 = Color3.fromRGB(29, 18, 63)
        }, 0.12)

        tween(marker, {
            BackgroundColor3 = Color3.fromRGB(44, 23, 77),
            Size = UDim2.fromOffset(28, 28),
        }, 0.12, Enum.EasingStyle.Back)

        tween(arrow, {
            TextColor3 = C.White,
            Position = UDim2.new(1, -25, 0, 0),
        }, 0.12)
    end))

    trackConnection(button.MouseLeave:Connect(function()
        tween(button, {
            BackgroundColor3 = C.Surface2
        }, 0.14)

        tween(marker, {
            BackgroundColor3 = Color3.fromRGB(31, 18, 57),
            Size = UDim2.fromOffset(26, 26),
        }, 0.14)

        tween(arrow, {
            TextColor3 = accent or C.SubText,
            Position = UDim2.new(1, -28, 0, 0),
        }, 0.14)
    end))

    return button
end

local function statCard(parent, title, subtitle, value, accent, xScale, widthScale)
    local card = New("Frame", {
        Parent = parent,
        BackgroundColor3 = C.Card,
        BorderSizePixel = 0,
        Size = UDim2.new(widthScale, -5, 1, 0),
        Position = UDim2.new(xScale, 0, 0, 0),
        ZIndex = 43,
    })
    Corner(card, 14)
    Border(card, accent, 1.15, 0.28)

    local glowBar = New("Frame", {
        Parent = card,
        BackgroundColor3 = accent,
        BackgroundTransparency = 0.55,
        BorderSizePixel = 0,
        Position = UDim2.fromOffset(11, 11),
        Size = UDim2.fromOffset(31, 3),
        ZIndex = 44,
    })
    Corner(glowBar, 99)

    local titleLabel = text(card, title, 11, UDim2.fromOffset(12, 23), BOLD, C.White)
    titleLabel.Size = UDim2.new(1, -24, 0, 22)

    local subtitleLabel = text(card, subtitle, 8, UDim2.fromOffset(12, 44), FONT, C.SubText)
    subtitleLabel.Size = UDim2.new(1, -24, 0, 28)
    subtitleLabel.TextWrapped = true

    local valueLabel = text(card, value, 8, UDim2.fromOffset(12, 76), BOLD, accent)
    valueLabel.Size = UDim2.new(1, -24, 0, 17)

    return card, valueLabel
end

