local function ensureFolder()
    if HAS.makefolder and HAS.isfolder then
        local ok, exists = pcall(isfolder, CONFIG_FOLDER)
        if ok and not exists then
            pcall(makefolder, CONFIG_FOLDER)
        end
    end
end

local function refreshProfileList()
    ProfileStatus.Text = "Profiles: " .. (#configNames > 0 and table.concat(configNames, ", ") or "None")
end

local function safeName(value)
    local name = tostring(value or "")
    name = name:gsub("[^%w_%-%s]", "")
    name = name:gsub("%s+", "_")
    return name:sub(1, 36)
end

local function pathFor(name)
    return CONFIG_FOLDER .. "/" .. name .. ".json"
end

local function configPayload()
    return {
        Version = 2,
        Tab = CurrentPage and CurrentPage.Name or "Home",
        SavedAt = os.time(),
        Brand = "NEXUS",
    }
end

if HAS.isfile and HAS.readfile and HAS.writefile then
    ensureFolder()

    if not isfile(CONFIG_INDEX) then
        pcall(function()
            writefile(CONFIG_INDEX, "{}")
        end)
    else
        pcall(function()
            local decoded = HttpService:JSONDecode(readfile(CONFIG_INDEX))
            if type(decoded) == "table" then
                for _, name in ipairs(decoded) do
                    if type(name) == "string" then
                        table.insert(configNames, name)
                    end
                end
            end
        end)
    end

    refreshProfileList()
end

trackConnection(SaveConfigButton.MouseButton1Click:Connect(function()
    local name = safeName(Input.Text)
    if name == "" then
        name = "Default"
        Input.Text = name
    end

    if not HAS.writefile then
        FSStatus.Text = "Filesystem unavailable"
        FSStatus.TextColor3 = C.Red
        return
    end

    ensureFolder()

    local ok = pcall(function()
        writefile(pathFor(name), HttpService:JSONEncode(configPayload()))

        if not table.find(configNames, name) then
            table.insert(configNames, name)
        end

        writefile(CONFIG_INDEX, HttpService:JSONEncode(configNames))
    end)

    if ok then
        FSStatus.Text = "Saved profile: " .. name
        FSStatus.TextColor3 = C.Green
        refreshProfileList()
    else
        FSStatus.Text = "Save failed"
        FSStatus.TextColor3 = C.Red
    end
end))

trackConnection(LoadConfigButton.MouseButton1Click:Connect(function()
    local name = safeName(Input.Text)
    if name == "" then name = "Default" end

    if HAS.isfile and HAS.readfile and isfile(pathFor(name)) then
        local ok = pcall(function()
            HttpService:JSONDecode(readfile(pathFor(name)))
        end)

        if ok then
            FSStatus.Text = "Loaded profile: " .. name
            FSStatus.TextColor3 = C.Cyan
        else
            FSStatus.Text = "Invalid profile"
            FSStatus.TextColor3 = C.Red
        end
    else
        FSStatus.Text = "Profile not found"
        FSStatus.TextColor3 = C.Red
    end
end))

trackConnection(DeleteConfigButton.MouseButton1Click:Connect(function()
    local name = safeName(Input.Text)
    if name == "" then return end

    if HAS.isfile and HAS.delfile and isfile(pathFor(name)) then
        pcall(function()
            delfile(pathFor(name))
        end)

        for i, value in ipairs(configNames) do
            if value == name then
                table.remove(configNames, i)
                break
            end
        end

        if HAS.writefile then
            pcall(function()
                writefile(CONFIG_INDEX, HttpService:JSONEncode(configNames))
            end)
        end

        FSStatus.Text = "Deleted profile: " .. name
        FSStatus.TextColor3 = C.Red
        refreshProfileList()
    else
        FSStatus.Text = "Profile not found"
        FSStatus.TextColor3 = C.Red
    end
end))

