local function selectTab(name)
    CurrentPage = Pages[name]

    for tabName, p in pairs(Pages) do
        p.Visible = (tabName == name)
    end

    for tabName, button in pairs(NavButtons) do
        local active = tabName == name
        local accent = TAB_ACCENTS[tabName] or C.Purple

        tween(
            button,
            {
                BackgroundColor3 = active and C.PurpleDeep or C.Surface,
            },
            0.16
        )

        local accentStrip = button:FindFirstChild("AccentStrip")
        local iconBubble = button:FindFirstChild("IconBubble")
        local tabText = button:FindFirstChild("TabText")

        if accentStrip then
            tween(accentStrip, {
                BackgroundTransparency = active and 0.04 or 1,
                Size = active and UDim2.fromOffset(3, 24) or UDim2.fromOffset(1, 18),
            }, 0.16)
        end

        if iconBubble then
            tween(iconBubble, {
                BackgroundColor3 = active and accent or C.Surface2,
            }, 0.16)
        end

        if tabText then
            tween(tabText, {
                TextColor3 = active and C.White or C.SubText,
            }, 0.16)
        end
    end
end

