--========================================================
-- DRAG WITH SCREEN BOUNDS
--========================================================

local dragging = false
local dragInput = nil
local dragStart = nil
local startPosition = nil

local function clampCenter(centerX, centerY)
    local viewport = viewportSize()
    local absolute = Main.AbsoluteSize

    local halfX = absolute.X / 2
    local halfY = absolute.Y / 2

    local minX = halfX + 5
    local maxX = math.max(minX, viewport.X - halfX - 5)

    local minY = halfY + 5
    local maxY = math.max(minY, viewport.Y - halfY - 5)

    return math.clamp(centerX, minX, maxX), math.clamp(centerY, minY, maxY)
end

local function dragUpdate(input)
    if not dragging or not dragStart or not startPosition then return end

    local delta = input.Position - dragStart

    local viewport = viewportSize()
    local baseX = viewport.X / 2 + startPosition.X.Offset
    local baseY = viewport.Y / 2 + startPosition.Y.Offset

    local x, y = clampCenter(baseX + delta.X, baseY + delta.Y)
    Main.Position = UDim2.fromOffset(x, y)
end

trackConnection(Header.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then

        dragging = true
        dragStart = input.Position

        local viewport = viewportSize()
        local current = Main.Position

        startPosition = UDim2.fromOffset(
            current.X.Offset - viewport.X / 2,
            current.Y.Offset - viewport.Y / 2
        )

        dragInput = input
    end
end))

trackConnection(Header.InputChanged:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseMovement
        or input.UserInputType == Enum.UserInputType.Touch then
        dragInput = input
    end
end))

trackConnection(UserInputService.InputChanged:Connect(function(input)
    if input == dragInput then
        dragUpdate(input)
    end
end))

trackConnection(UserInputService.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        dragging = false
    end
end))

