local function openMenu()
    setOpenButtonVisible(false)

    Main.Visible = true
    MainScale.Scale = 0.88

    local viewport = viewportSize()
    local x = viewport.X / 2
    local y = viewport.Y / 2
    x, y = clampCenter(x, y)
    Main.Position = UDim2.fromOffset(x, y)

    tween(MainScale, {Scale = 1}, 0.34, Enum.EasingStyle.Back)
    tween(OuterGlow, {BackgroundTransparency = 0.94}, 0.18)
end

local function closeMenu()
    tween(MainScale, {Scale = 0.88}, 0.20, Enum.EasingStyle.Quint)

    task.delay(0.19, function()
        if Main then
            Main.Visible = false
        end
        setOpenButtonVisible(true)
    end)
end

