--========================================================
-- LIVE TELEMETRY
--========================================================

local frameStart = os.clock()
local frameCount = 0

trackConnection(RunService.RenderStepped:Connect(function()
    frameCount += 1
    local now = os.clock()

    if now - frameStart >= 0.5 then
        local fps = math.floor(frameCount / (now - frameStart) + 0.5)
        FPSLabel.Text = "FPS: " .. tostring(fps)
        frameCount = 0
        frameStart = now
    end

    local pingOk, ping = pcall(function()
        return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
    end)

    if pingOk and type(ping) == "number" then
        PingLabel.Text = "PING: " .. tostring(math.floor(ping + 0.5)) .. "ms"
    end

    PlaceLabel.Text = "PLACE: " .. tostring(game.PlaceId)
end))

local function updateCharacterStats()
    local character = LocalPlayer.Character
    if not character then return end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end

    local health = math.max(0, humanoid.Health)
    local maxHealth = math.max(1, humanoid.MaxHealth)
    local ratio = math.clamp(health / maxHealth, 0, 1)

    HealthFill.Size = UDim2.new(ratio, 0, 1, 0)
    HealthValue.Text = string.format(
        "%d / %d",
        math.floor(health + 0.5),
        math.floor(maxHealth + 0.5)
    )

    SpeedValue.Text = tostring(math.floor(humanoid.WalkSpeed + 0.5))
end

trackConnection(RunService.Heartbeat:Connect(updateCharacterStats))

trackConnection(LocalPlayer.CharacterAdded:Connect(function(character)
    local humanoid = character:WaitForChild("Humanoid", 6)
    if humanoid then
        task.wait(0.2)
        updateCharacterStats()
    end
end))

