--========================================================
-- RESPONSIVE LAYOUT
--========================================================

local lastMobileState = nil

local function updateResponsive()
    local viewport = viewportSize()
    local mobile = viewport.X <= 540
    local tablet = viewport.X > 540 and viewport.X <= 900

    Main.Size = calculateWindow()

    if mobile then
        Sidebar.Size = UDim2.new(0, 58, 1, -94)
        Content.Position = UDim2.fromOffset(72, 81)
        Content.Size = UDim2.new(1, -85, 1, -94)

        UserCard.Visible = false

        for _, button in pairs(NavButtons) do
            local tabText = button:FindFirstChild("TabText")
            local arrow = button:FindFirstChild("TextLabel")
            if tabText then
                tabText.Visible = false
            end

            if arrow and arrow.Text == "›" then
                arrow.Visible = false
            end
        end
    elseif tablet then
        Sidebar.Size = UDim2.new(0, 170, 1, -94)
        Content.Position = UDim2.fromOffset(184, 81)
        Content.Size = UDim2.new(1, -197, 1, -94)

        UserCard.Visible = true

        for _, button in pairs(NavButtons) do
            local tabText = button:FindFirstChild("TabText")
            if tabText then tabText.Visible = true end
        end
    else
        Sidebar.Size = UDim2.new(0, 205, 1, -94)
        Content.Position = UDim2.fromOffset(229, 81)
        Content.Size = UDim2.new(1, -242, 1, -94)

        UserCard.Visible = true

        for _, button in pairs(NavButtons) do
            local tabText = button:FindFirstChild("TabText")
            if tabText then tabText.Visible = true end
        end
    end

    if lastMobileState ~= mobile then
        lastMobileState = mobile
    end
end

task.spawn(function()
    while ScreenGui.Parent do
        updateResponsive()
        task.wait(0.8)
    end
end)

